using Microsoft.Data.Sqlite;
using NetworkHelper.Domain;
using NetworkHelper.Services;

namespace NetworkHelper.Data;

public sealed class Database
{
    private readonly string _connectionString;
    public string StoragePath { get; }
    public Database(string? storageRoot = null)
    {
        if(!string.IsNullOrWhiteSpace(storageRoot))
        {
            if(!EnsureWritable(storageRoot)) throw new UnauthorizedAccessException($"The database folder is not writable: {storageRoot}");
            StoragePath=Path.Combine(storageRoot,"network-helper.db"); _connectionString=$"Data Source={StoragePath}"; return;
        }
        var preferred = Path.Combine(AppContext.BaseDirectory, "Data");
        var fallback = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "NetworkHelper");
        var root = EnsureWritable(preferred) ? preferred : EnsureWritable(fallback) ? fallback : throw new UnauthorizedAccessException("Network Helper could not find a writable folder for its local database.");
        StoragePath = Path.Combine(root, "network-helper.db");
        _connectionString = $"Data Source={StoragePath}";
    }
    private static bool EnsureWritable(string path)
    {
        try { Directory.CreateDirectory(path); var probe=Path.Combine(path,$".write-{Guid.NewGuid():N}"); using(File.Create(probe)){} File.Delete(probe); return true; }
        catch(UnauthorizedAccessException) { return false; }
        catch(IOException) { return false; }
    }
    private SqliteConnection Open() { var c = new SqliteConnection(_connectionString); c.Open(); c.Execute("PRAGMA foreign_keys=ON;"); return c; }
    public void Initialize()
    {
        using var c = Open();
        c.Execute("""
        CREATE TABLE IF NOT EXISTS companies(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
        CREATE TABLE IF NOT EXISTS sites(id INTEGER PRIMARY KEY, company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE, name TEXT NOT NULL, address TEXT, UNIQUE(company_id,name));
        CREATE TABLE IF NOT EXISTS devices(id INTEGER PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, name TEXT NOT NULL, ip_address TEXT, mac_address TEXT, serial_number TEXT, vendor TEXT, model TEXT, device_type TEXT, zone TEXT, description TEXT);
        CREATE TABLE IF NOT EXISTS networks(id INTEGER PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, name TEXT NOT NULL, cidr TEXT NOT NULL, vlan_id INTEGER, zone TEXT, UNIQUE(site_id,cidr,vlan_id));
        CREATE TABLE IF NOT EXISTS evidence_sources(id INTEGER PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, file_name TEXT NOT NULL, source_type TEXT NOT NULL, imported_at TEXT NOT NULL, content_hash TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS facts(id INTEGER PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, entity_type TEXT NOT NULL, entity_id INTEGER NOT NULL, field_name TEXT NOT NULL, value TEXT NOT NULL, confidence REAL NOT NULL, status TEXT NOT NULL CHECK(status IN ('inferred','confirmed','superseded','conflicting')));
        CREATE TABLE IF NOT EXISTS fact_evidence(fact_id INTEGER NOT NULL REFERENCES facts(id) ON DELETE CASCADE, source_id INTEGER NOT NULL REFERENCES evidence_sources(id) ON DELETE CASCADE, PRIMARY KEY(fact_id,source_id));
        CREATE TABLE IF NOT EXISTS conflicts(id INTEGER PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, device_id INTEGER REFERENCES devices(id) ON DELETE CASCADE, entity_name TEXT NOT NULL, field_name TEXT NOT NULL, existing_value TEXT, new_value TEXT, source_id INTEGER NOT NULL REFERENCES evidence_sources(id), status TEXT NOT NULL DEFAULT 'unresolved', resolved_at TEXT);
        CREATE TABLE IF NOT EXISTS vlans(id INTEGER PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, vlan_number INTEGER NOT NULL, name TEXT, zone TEXT, UNIQUE(site_id,vlan_number));
        CREATE TABLE IF NOT EXISTS interfaces(id INTEGER PRIMARY KEY, device_id INTEGER NOT NULL REFERENCES devices(id) ON DELETE CASCADE, name TEXT NOT NULL, ip_address TEXT, mac_address TEXT);
        CREATE TABLE IF NOT EXISTS connections(id INTEGER PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, from_interface_id INTEGER REFERENCES interfaces(id), to_interface_id INTEGER REFERENCES interfaces(id), description TEXT);
        CREATE TABLE IF NOT EXISTS management_paths(id INTEGER PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, target_device_id INTEGER REFERENCES devices(id), description TEXT);
        CREATE TABLE IF NOT EXISTS incidents(id INTEGER PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, title TEXT NOT NULL, notes TEXT, occurred_at TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS topology_relationships(id INTEGER PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, from_device_id INTEGER NOT NULL REFERENCES devices(id) ON DELETE CASCADE, to_device_id INTEGER NOT NULL REFERENCES devices(id) ON DELETE CASCADE, relationship_type TEXT NOT NULL DEFAULT 'CONNECTED_TO', source_id INTEGER NOT NULL REFERENCES evidence_sources(id), source_page TEXT NOT NULL, from_shape_id TEXT, to_shape_id TEXT, confidence REAL NOT NULL, status TEXT NOT NULL CHECK(status IN ('inferred','confirmed','conflicting','superseded')));
        CREATE TABLE IF NOT EXISTS topology_relationship_evidence(relationship_id INTEGER NOT NULL REFERENCES topology_relationships(id) ON DELETE CASCADE, source_id INTEGER NOT NULL REFERENCES evidence_sources(id) ON DELETE CASCADE, source_page TEXT NOT NULL, from_shape_id TEXT, to_shape_id TEXT, PRIMARY KEY(relationship_id,source_id,source_page));
        CREATE TABLE IF NOT EXISTS entity_relationships(id INTEGER PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, from_entity_type TEXT NOT NULL, from_entity_id INTEGER, from_entity_name TEXT NOT NULL, to_entity_type TEXT NOT NULL, to_entity_id INTEGER, to_entity_name TEXT NOT NULL, relationship_type TEXT NOT NULL, source_id INTEGER NOT NULL REFERENCES evidence_sources(id), source_page TEXT, confidence REAL NOT NULL, status TEXT NOT NULL CHECK(status IN ('inferred','confirmed','conflicting','superseded')), basis TEXT, created_at TEXT NOT NULL, last_verified_at TEXT);
        CREATE INDEX IF NOT EXISTS ix_relationships_site_from ON entity_relationships(site_id,from_entity_type,from_entity_id);
        CREATE INDEX IF NOT EXISTS ix_relationships_site_to ON entity_relationships(site_id,to_entity_type,to_entity_id);
        CREATE TABLE IF NOT EXISTS relationship_evidence(relationship_id INTEGER NOT NULL REFERENCES entity_relationships(id) ON DELETE CASCADE, source_id INTEGER NOT NULL REFERENCES evidence_sources(id) ON DELETE CASCADE, basis TEXT, PRIMARY KEY(relationship_id,source_id));
        CREATE TABLE IF NOT EXISTS relationship_conflicts(id INTEGER PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, existing_relationship_id INTEGER NOT NULL REFERENCES entity_relationships(id), proposed_relationship_id INTEGER NOT NULL REFERENCES entity_relationships(id), status TEXT NOT NULL DEFAULT 'unresolved', created_at TEXT NOT NULL, resolved_at TEXT);
        CREATE TABLE IF NOT EXISTS command_catalog(id INTEGER PRIMARY KEY, command_key TEXT NOT NULL UNIQUE, platform TEXT NOT NULL, category TEXT NOT NULL, command_text TEXT NOT NULL, purpose TEXT NOT NULL, risk_level TEXT NOT NULL, notes TEXT, is_built_in INTEGER NOT NULL DEFAULT 1, is_enabled INTEGER NOT NULL DEFAULT 1);
        CREATE TABLE IF NOT EXISTS troubleshooting_sessions(id INTEGER PRIMARY KEY, site_id INTEGER NOT NULL REFERENCES sites(id) ON DELETE CASCADE, target_device_id INTEGER REFERENCES devices(id) ON DELETE SET NULL, target_name TEXT, description TEXT NOT NULL, issue_type TEXT NOT NULL, summary TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS troubleshooting_steps(id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES troubleshooting_sessions(id) ON DELETE CASCADE, step_order INTEGER NOT NULL, title TEXT NOT NULL, action TEXT NOT NULL, command_text TEXT, purpose TEXT NOT NULL, evidence TEXT NOT NULL, confidence REAL NOT NULL, status TEXT NOT NULL DEFAULT 'pending', relationship_id INTEGER, UNIQUE(session_id,step_order));
        CREATE INDEX IF NOT EXISTS ix_troubleshooting_sessions_site ON troubleshooting_sessions(site_id,created_at DESC);
        """);
        EnsureColumn(c,"networks","zone","TEXT"); EnsureColumn(c,"vlans","zone","TEXT"); EnsureColumn(c,"devices","device_type","TEXT"); EnsureColumn(c,"devices","zone","TEXT"); EnsureColumn(c,"devices","description","TEXT"); EnsureColumn(c,"entity_relationships","scope_key","TEXT");
        c.Execute("DELETE FROM networks WHERE id NOT IN (SELECT MIN(id) FROM networks GROUP BY site_id,cidr,COALESCE(vlan_id,-1),COALESCE(zone,''))");
        // Bring connectors imported by earlier builds into the generic graph once.
        c.Execute("""
        INSERT INTO entity_relationships(site_id,from_entity_type,from_entity_id,from_entity_name,to_entity_type,to_entity_id,to_entity_name,relationship_type,source_id,source_page,confidence,status,basis,created_at,last_verified_at)
        SELECT t.site_id,'device',t.from_device_id,a.name,'device',t.to_device_id,b.name,t.relationship_type,t.source_id,t.source_page,t.confidence,t.status,
               'Visio connector shapes '||COALESCE(t.from_shape_id,'?')||' and '||COALESCE(t.to_shape_id,'?'),e.imported_at,e.imported_at
        FROM topology_relationships t JOIN devices a ON a.id=t.from_device_id JOIN devices b ON b.id=t.to_device_id JOIN evidence_sources e ON e.id=t.source_id
        WHERE NOT EXISTS(SELECT 1 FROM entity_relationships r WHERE r.site_id=t.site_id AND r.relationship_type=t.relationship_type AND r.status<>'superseded' AND ((r.from_entity_id=t.from_device_id AND r.to_entity_id=t.to_device_id) OR (r.from_entity_id=t.to_device_id AND r.to_entity_id=t.from_device_id)));
        INSERT OR IGNORE INTO relationship_evidence(relationship_id,source_id,basis)
        SELECT r.id,r.source_id,r.basis FROM entity_relationships r;
        """);
        SeedCommands(c);
    }
    public List<Company> Companies() { using var c=Open(); return c.Query(r=>new Company(r.GetInt64(0),r.GetString(1)),"SELECT id,name FROM companies ORDER BY name"); }
    public long AddCompany(string name) { using var c=Open(); return c.Insert("INSERT INTO companies(name) VALUES($v); SELECT last_insert_rowid();",("$v",name.Trim())); }
    public void RenameCompany(long id,string name) { using var c=Open(); c.Execute("UPDATE companies SET name=$n WHERE id=$id",("$n",name.Trim()),("$id",id)); }
    public void DeleteCompany(long id) { using var c=Open(); c.Execute("DELETE FROM companies WHERE id=$id",("$id",id)); }
    public List<Site> Sites(long companyId) { using var c=Open(); return c.Query(r=>new Site(r.GetInt64(0),r.GetInt64(1),r.GetString(2),r.IsDBNull(3)?null:r.GetString(3)),"SELECT id,company_id,name,address FROM sites WHERE company_id=$id ORDER BY name",("$id",companyId)); }
    public long AddSite(long companyId,string name,string? address) { using var c=Open(); return c.Insert("INSERT INTO sites(company_id,name,address) VALUES($c,$n,$a); SELECT last_insert_rowid();",("$c",companyId),("$n",name.Trim()),("$a",address)); }
    public void UpdateSite(long id,string name,string? address) { using var c=Open(); c.Execute("UPDATE sites SET name=$n,address=$a WHERE id=$id",("$n",name.Trim()),("$a",address),("$id",id)); }
    public void DeleteSite(long id) { using var c=Open(); c.Execute("DELETE FROM sites WHERE id=$id",("$id",id)); }
    public void MergeSites(long sourceSiteId,long targetSiteId)
    {
        if(sourceSiteId==targetSiteId)throw new InvalidOperationException("A site cannot be merged into itself.");
        var source=Devices(sourceSiteId);var target=Devices(targetSiteId);
        using var c=Open();using var tx=c.BeginTransaction();
        foreach(var device in source)
        {
            var row=new ImportRow(device.Name,device.IpAddress,device.MacAddress,device.SerialNumber,device.Vendor,device.Model,null,null);var match=EntityMatcher.BestMatch(row,target);
            if(match is null){c.Execute("UPDATE devices SET site_id=$t WHERE id=$d",("$t",targetSiteId),("$d",device.Id));c.Execute("UPDATE facts SET site_id=$t WHERE entity_type='device' AND entity_id=$d",("$t",targetSiteId),("$d",device.Id));target.Add(device with{SiteId=targetSiteId});continue;}
            var evidence=c.Insert("INSERT INTO evidence_sources(site_id,file_name,source_type,imported_at,content_hash) VALUES($s,$f,'SITE_MERGE',$at,$h); SELECT last_insert_rowid();",("$s",targetSiteId),("$f",$"Merged site {sourceSiteId}"),("$at",DateTimeOffset.Now.ToString("O")),("$h",$"site-merge-{sourceSiteId}-{targetSiteId}-{device.Id}"));
            foreach(var conflict in EntityMatcher.Conflicts(row,match))c.Execute("INSERT INTO conflicts(site_id,device_id,entity_name,field_name,existing_value,new_value,source_id) VALUES($s,$d,$n,$f,$old,$new,$src)",("$s",targetSiteId),("$d",match.Id),("$n",match.Name),("$f",conflict.Field),("$old",conflict.Existing),("$new",conflict.Proposed),("$src",evidence));
            c.Execute("UPDATE facts SET site_id=$s,entity_id=$to WHERE entity_type='device' AND entity_id=$from",("$s",targetSiteId),("$to",match.Id),("$from",device.Id));
            c.Execute("UPDATE conflicts SET site_id=$s,device_id=$to WHERE device_id=$from",("$s",targetSiteId),("$to",match.Id),("$from",device.Id));
            c.Execute("UPDATE interfaces SET device_id=$to WHERE device_id=$from",("$to",match.Id),("$from",device.Id));
            c.Execute("UPDATE management_paths SET site_id=$s,target_device_id=$to WHERE target_device_id=$from",("$s",targetSiteId),("$to",match.Id),("$from",device.Id));
            c.Execute("UPDATE topology_relationships SET from_device_id=$to WHERE from_device_id=$from",("$to",match.Id),("$from",device.Id));c.Execute("UPDATE topology_relationships SET to_device_id=$to WHERE to_device_id=$from",("$to",match.Id),("$from",device.Id));
            c.Execute("UPDATE entity_relationships SET from_entity_id=$to,from_entity_name=$n WHERE from_entity_type='device' AND from_entity_id=$from",("$to",match.Id),("$n",match.Name),("$from",device.Id));c.Execute("UPDATE entity_relationships SET to_entity_id=$to,to_entity_name=$n WHERE to_entity_type='device' AND to_entity_id=$from",("$to",match.Id),("$n",match.Name),("$from",device.Id));
            c.Execute("DELETE FROM topology_relationships WHERE from_device_id=to_device_id");c.Execute("DELETE FROM devices WHERE id=$id",("$id",device.Id));
        }
        c.Execute("INSERT OR IGNORE INTO networks(site_id,name,cidr,vlan_id,zone) SELECT $t,name,cidr,vlan_id,zone FROM networks WHERE site_id=$s",("$t",targetSiteId),("$s",sourceSiteId));c.Execute("DELETE FROM networks WHERE site_id=$s",("$s",sourceSiteId));
        c.Execute("INSERT OR IGNORE INTO vlans(site_id,vlan_number,name,zone) SELECT $t,vlan_number,name,zone FROM vlans WHERE site_id=$s",("$t",targetSiteId),("$s",sourceSiteId));c.Execute("DELETE FROM vlans WHERE site_id=$s",("$s",sourceSiteId));
        foreach(var table in new[]{"evidence_sources","conflicts","connections","management_paths","incidents","topology_relationships","entity_relationships","relationship_conflicts"})c.Execute($"UPDATE {table} SET site_id=$t WHERE site_id=$s",("$t",targetSiteId),("$s",sourceSiteId));
        c.Execute("DELETE FROM sites WHERE id=$s",("$s",sourceSiteId));tx.Commit();
    }
    public List<Device> Devices(long siteId) { using var c=Open(); return c.Query(r=>new Device(r.GetInt64(0),r.GetInt64(1),r.GetString(2),S(r,3),S(r,4),S(r,5),S(r,6),S(r,7),S(r,8),S(r,9),S(r,10)),"SELECT id,site_id,name,ip_address,mac_address,serial_number,vendor,model,device_type,zone,description FROM devices WHERE site_id=$id ORDER BY COALESCE(zone,''),COALESCE(device_type,''),name",("$id",siteId)); }
    public long AddDevice(long siteId,string name,string? ip,string? mac,string? serial,string? vendor,string? model,string? type,string? zone,string? description){using var c=Open();var id=c.Insert("INSERT INTO devices(site_id,name,ip_address,mac_address,serial_number,vendor,model,device_type,zone,description) VALUES($s,$n,$ip,$mac,$ser,$v,$m,$t,$z,$d); SELECT last_insert_rowid();",("$s",siteId),("$n",name),("$ip",ip),("$mac",mac),("$ser",serial),("$v",vendor),("$m",model),("$t",type),("$z",zone),("$d",description));RecordManual(c,siteId,"device",id,"Created device",new[]{("name",name),("ip_address",ip),("mac_address",mac),("serial_number",serial),("vendor",vendor),("model",model),("device_type",type),("zone",zone),("description",description)});return id;}
    public void UpdateDevice(Device d){using var c=Open();c.Execute("UPDATE devices SET name=$n,ip_address=$ip,mac_address=$mac,serial_number=$ser,vendor=$v,model=$m,device_type=$t,zone=$z,description=$desc WHERE id=$id",("$n",d.Name),("$ip",d.IpAddress),("$mac",d.MacAddress),("$ser",d.SerialNumber),("$v",d.Vendor),("$m",d.Model),("$t",d.DeviceType),("$z",d.Zone),("$desc",d.Description),("$id",d.Id));c.Execute("UPDATE entity_relationships SET from_entity_name=$n WHERE from_entity_type='device' AND from_entity_id=$id",("$n",d.Name),("$id",d.Id));c.Execute("UPDATE entity_relationships SET to_entity_name=$n WHERE to_entity_type='device' AND to_entity_id=$id",("$n",d.Name),("$id",d.Id));RecordManual(c,d.SiteId,"device",d.Id,"Edited device",new[]{("name",d.Name),("ip_address",d.IpAddress),("mac_address",d.MacAddress),("serial_number",d.SerialNumber),("vendor",d.Vendor),("model",d.Model),("device_type",d.DeviceType),("zone",d.Zone),("description",d.Description)});}
    public void DeleteDevice(long id){using var c=Open();c.Execute("DELETE FROM relationship_conflicts WHERE existing_relationship_id IN(SELECT id FROM entity_relationships WHERE (from_entity_type='device' AND from_entity_id=$id) OR (to_entity_type='device' AND to_entity_id=$id)) OR proposed_relationship_id IN(SELECT id FROM entity_relationships WHERE (from_entity_type='device' AND from_entity_id=$id) OR (to_entity_type='device' AND to_entity_id=$id))",("$id",id));c.Execute("DELETE FROM entity_relationships WHERE (from_entity_type='device' AND from_entity_id=$id) OR (to_entity_type='device' AND to_entity_id=$id)",("$id",id));c.Execute("DELETE FROM devices WHERE id=$id",("$id",id));}
    public List<NetworkRecord> Networks(long siteId) { using var c=Open(); return c.Query(r=>new NetworkRecord(r.GetInt64(0),r.GetInt64(1),r.GetString(2),r.GetString(3),r.IsDBNull(4)?null:r.GetInt32(4),S(r,5)),"SELECT id,site_id,name,cidr,vlan_id,zone FROM networks WHERE site_id=$id ORDER BY zone,cidr",("$id",siteId)); }
    public long AddNetwork(long siteId,string name,string cidr,int? vlan,string? zone){using var c=Open();var id=c.Insert("INSERT INTO networks(site_id,name,cidr,vlan_id,zone) VALUES($s,$n,$c,$v,$z); SELECT last_insert_rowid();",("$s",siteId),("$n",name),("$c",cidr),("$v",vlan),("$z",zone));if(vlan.HasValue)c.Execute("INSERT OR IGNORE INTO vlans(site_id,vlan_number,name,zone) VALUES($s,$v,$n,$z)",("$s",siteId),("$v",vlan),("$n",name),("$z",zone));RecordManual(c,siteId,"network",id,"Created network",new[]{("name",name),("cidr",cidr),("vlan_id",vlan?.ToString()),("zone",zone)});return id;}
    public void UpdateNetwork(NetworkRecord n){using var c=Open();c.Execute("UPDATE networks SET name=$n,cidr=$c,vlan_id=$v,zone=$z WHERE id=$id",("$n",n.Name),("$c",n.Cidr),("$v",n.VlanId),("$z",n.Zone),("$id",n.Id));c.Execute("UPDATE entity_relationships SET from_entity_name=$n WHERE from_entity_type='subnet' AND from_entity_id=$id",("$n",n.Cidr),("$id",n.Id));c.Execute("UPDATE entity_relationships SET to_entity_name=$n WHERE to_entity_type='subnet' AND to_entity_id=$id",("$n",n.Cidr),("$id",n.Id));if(n.VlanId.HasValue)c.Execute("INSERT OR IGNORE INTO vlans(site_id,vlan_number,name,zone) VALUES($s,$v,$n,$z)",("$s",n.SiteId),("$v",n.VlanId),("$n",n.Name),("$z",n.Zone));RecordManual(c,n.SiteId,"network",n.Id,"Edited network",new[]{("name",n.Name),("cidr",n.Cidr),("vlan_id",n.VlanId?.ToString()),("zone",n.Zone)});}
    public void DeleteNetwork(long id){using var c=Open();c.Execute("DELETE FROM relationship_conflicts WHERE existing_relationship_id IN(SELECT id FROM entity_relationships WHERE (from_entity_type='subnet' AND from_entity_id=$id) OR (to_entity_type='subnet' AND to_entity_id=$id)) OR proposed_relationship_id IN(SELECT id FROM entity_relationships WHERE (from_entity_type='subnet' AND from_entity_id=$id) OR (to_entity_type='subnet' AND to_entity_id=$id))",("$id",id));c.Execute("DELETE FROM entity_relationships WHERE (from_entity_type='subnet' AND from_entity_id=$id) OR (to_entity_type='subnet' AND to_entity_id=$id)",("$id",id));c.Execute("DELETE FROM networks WHERE id=$id",("$id",id));}
    public List<Conflict> Conflicts(long siteId) { using var c=Open(); return c.Query(r=>new Conflict(r.GetInt64(0),r.GetInt64(1),r.IsDBNull(2)?null:r.GetInt64(2),r.GetString(3),r.GetString(4),S(r,5),S(r,6),r.GetString(7),r.GetString(8)),"SELECT c.id,c.site_id,c.device_id,c.entity_name,c.field_name,c.existing_value,c.new_value,c.status,e.file_name FROM conflicts c JOIN evidence_sources e ON e.id=c.source_id WHERE c.site_id=$id ORDER BY c.status DESC,c.id DESC",("$id",siteId)); }
    public List<(string File,string Type,string Imported)> Sources(long siteId) { using var c=Open(); return c.Query(r=>(r.GetString(0),r.GetString(1),r.GetString(2)),"SELECT file_name,source_type,imported_at FROM evidence_sources WHERE site_id=$id ORDER BY id DESC",("$id",siteId)); }
    public List<CommandKnowledge> Commands(string? query=null)
    {
        using var c=Open();var q=query?.Trim();return c.Query(r=>new CommandKnowledge(r.GetInt64(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6),S(r,7),r.GetInt32(8)!=0),"SELECT id,command_key,platform,category,command_text,purpose,risk_level,notes,is_built_in FROM command_catalog WHERE is_enabled=1 AND ($q IS NULL OR platform LIKE $like OR category LIKE $like OR command_text LIKE $like OR purpose LIKE $like) ORDER BY platform,category,purpose",("$q",string.IsNullOrWhiteSpace(q)?null:q),("$like",string.IsNullOrWhiteSpace(q)?null:$"%{q}%"));
    }
    public CommandKnowledge? CommandByKey(string key)=>Commands().FirstOrDefault(x=>x.Key.Equals(key,StringComparison.OrdinalIgnoreCase));
    public long AddCommand(string platform,string category,string command,string purpose,string risk,string? notes){using var c=Open();return c.Insert("INSERT INTO command_catalog(command_key,platform,category,command_text,purpose,risk_level,notes,is_built_in,is_enabled) VALUES($k,$p,$c,$cmd,$purpose,$risk,$notes,0,1); SELECT last_insert_rowid();",("$k","custom-"+Guid.NewGuid().ToString("N")),("$p",platform.Trim()),("$c",category.Trim()),("$cmd",command.Trim()),("$purpose",purpose.Trim()),("$risk",risk),("$notes",notes));}
    public void UpdateCommand(CommandKnowledge command){using var c=Open();c.Execute("UPDATE command_catalog SET platform=$p,category=$c,command_text=$cmd,purpose=$purpose,risk_level=$risk,notes=$notes WHERE id=$id",("$p",command.Platform.Trim()),("$c",command.Category.Trim()),("$cmd",command.CommandText.Trim()),("$purpose",command.Purpose.Trim()),("$risk",command.RiskLevel),("$notes",command.Notes),("$id",command.Id));}
    public void DeleteCommand(long id){using var c=Open();c.Execute("UPDATE command_catalog SET is_enabled=0 WHERE id=$id",("$id",id));}
    public long SaveTroubleshootingPlan(long siteId,string description,TroubleshootingPlan plan)
    {
        using var c=Open();using var tx=c.BeginTransaction();var now=DateTimeOffset.Now.ToString("O");var session=c.Insert("INSERT INTO troubleshooting_sessions(site_id,target_device_id,target_name,description,issue_type,summary,status,created_at,updated_at) VALUES($s,$d,$n,$r,$i,$summary,'open',$at,$at); SELECT last_insert_rowid();",("$s",siteId),("$d",plan.Target?.Id),("$n",plan.Target?.Name),("$r",description.Trim()),("$i",plan.IssueType),("$summary",plan.Summary),("$at",now));foreach(var step in plan.Steps)c.Execute("INSERT INTO troubleshooting_steps(session_id,step_order,title,action,command_text,purpose,evidence,confidence,status,relationship_id) VALUES($s,$o,$t,$a,$c,$p,$e,$confidence,$status,$r)",("$s",session),("$o",step.Order),("$t",step.Title),("$a",step.Action),("$c",step.Command),("$p",step.Purpose),("$e",step.Evidence),("$confidence",step.Confidence),("$status",step.Status),("$r",step.RelationshipId));tx.Commit();return session;
    }
    public List<TroubleshootingSession> TroubleshootingSessions(long siteId){using var c=Open();return c.Query(r=>new TroubleshootingSession(r.GetInt64(0),r.GetInt64(1),r.IsDBNull(2)?null:r.GetInt64(2),S(r,3),r.GetString(4),r.GetString(5),r.GetString(6),r.GetString(7),r.GetString(8),r.GetString(9)),"SELECT id,site_id,target_device_id,target_name,description,issue_type,summary,status,created_at,updated_at FROM troubleshooting_sessions WHERE site_id=$s ORDER BY id DESC",("$s",siteId));}
