    public List<EntityRef> Entities(long siteId)
    {
        using var c=Open();var list=new List<EntityRef>{new("access_node",null,"Current workstation")};list.AddRange(c.Query(r=>new EntityRef("device",r.GetInt64(0),r.GetString(1)),"SELECT id,name FROM devices WHERE site_id=$s ORDER BY name",("$s",siteId)));list.AddRange(c.Query(r=>new EntityRef("subnet",r.GetInt64(0),r.GetString(1)),"SELECT id,cidr FROM networks WHERE site_id=$s ORDER BY cidr",("$s",siteId)));list.AddRange(c.Query(r=>new EntityRef("vlan",r.GetInt64(0),$"VLAN {r.GetInt32(1)} - {S(r,2)}"),"SELECT id,vlan_number,name FROM vlans WHERE site_id=$s ORDER BY vlan_number",("$s",siteId)));return list;
