    public List<Relationship> Relationships(long siteId,long? deviceId=null)
    {
        using var c=Open();var where=deviceId.HasValue?" AND ((r.from_entity_type='device' AND r.from_entity_id=$d) OR (r.to_entity_type='device' AND r.to_entity_id=$d))":"";var ps=deviceId.HasValue?new[]{("$s",(object?)siteId),("$d",(object?)deviceId)}:new[]{("$s",(object?)siteId)};return c.Query(r=>new Relationship(r.GetInt64(0),r.GetInt64(1),r.GetString(2),r.IsDBNull(3)?null:r.GetInt64(3),r.GetString(4),r.GetString(5),r.IsDBNull(6)?null:r.GetInt64(6),r.GetString(7),r.GetString(8),r.GetString(9),S(r,10),r.GetDouble(11),r.GetString(12),r.GetString(13),S(r,14),S(r,15)),$"SELECT r.id,r.site_id,r.from_entity_type,r.from_entity_id,r.from_entity_name,r.to_entity_type,r.to_entity_id,r.to_entity_name,r.relationship_type,e.file_name||CASE WHEN (SELECT COUNT(*) FROM relationship_evidence re WHERE re.relationship_id=r.id)>1 THEN ' (+'||((SELECT COUNT(*) FROM relationship_evidence re WHERE re.relationship_id=r.id)-1)||' evidence)' ELSE '' END,r.source_page,r.confidence,r.status,r.created_at,r.last_verified_at,CASE WHEN r.scope_key IS NULL THEN r.basis ELSE COALESCE(r.basis||' · ','')||'Context: '||r.scope_key END FROM entity_relationships r JOIN evidence_sources e ON e.id=r.source_id WHERE r.site_id=$s{where} ORDER BY r.relationship_type,r.from_entity_name,r.to_entity_name",ps);
    }
    public long AddRelationship(long siteId,EntityRef from,EntityRef to,string type,double confidence=1,string status="confirmed",string? basis=null,string? scopeKey=null)
    {
        if(!RelationshipTypes.All.Contains(type))throw new InvalidOperationException("Unsupported relationship type.");if(string.IsNullOrWhiteSpace(from.Name)||string.IsNullOrWhiteSpace(to.Name))throw new InvalidOperationException("Both relationship endpoints are required.");using var c=Open();using var tx=c.BeginTransaction();var now=DateTimeOffset.Now.ToString("O");var source=c.Insert("INSERT INTO evidence_sources(site_id,file_name,source_type,imported_at,content_hash) VALUES($s,'Manual relationship','MANUAL',$at,$h); SELECT last_insert_rowid();",("$s",siteId),("$at",now),("$h",Guid.NewGuid().ToString("N")));var id=AddSourcedRelationship(c,siteId,from,to,type,source,null,confidence,status,basis,scopeKey);tx.Commit();return id;
    }
    internal long AddSourcedRelationship(SqliteConnection c,long siteId,EntityRef from,EntityRef to,string type,long source,string? sourcePage,double confidence,string status,string? basis,string? scopeKey=null)
    {
        if(!RelationshipTypes.All.Contains(type))throw new InvalidOperationException("Unsupported relationship type.");var now=DateTimeOffset.Now.ToString("O");
        var exact=c.OptionalLong("SELECT id FROM entity_relationships WHERE site_id=$s AND from_entity_type=$ft AND COALESCE(from_entity_id,-1)=COALESCE($fi,-1) AND from_entity_name=$fn COLLATE NOCASE AND to_entity_type=$tt AND COALESCE(to_entity_id,-1)=COALESCE($ti,-1) AND to_entity_name=$tn COLLATE NOCASE AND relationship_type=$rt AND status<>'superseded' LIMIT 1",("$s",siteId),("$ft",from.Type),("$fi",from.Id),("$fn",from.Name),("$tt",to.Type),("$ti",to.Id),("$tn",to.Name),("$rt",type));
        if(exact.HasValue){var already=c.OptionalLong("SELECT 1 FROM relationship_evidence WHERE relationship_id=$r AND source_id=$s",("$r",exact.Value),("$s",source)).HasValue;c.Execute("INSERT OR IGNORE INTO relationship_evidence(relationship_id,source_id,basis) VALUES($r,$s,$b)",("$r",exact.Value),("$s",source),("$b",basis));c.Execute("UPDATE entity_relationships SET confidence=MIN(0.99,MAX(confidence,$c)+$boost),last_verified_at=$at WHERE id=$id",("$c",confidence),("$boost",already?0:.05),("$at",now),("$id",exact.Value));return exact.Value;}
        var id=c.Insert("INSERT INTO entity_relationships(site_id,from_entity_type,from_entity_id,from_entity_name,to_entity_type,to_entity_id,to_entity_name,relationship_type,source_id,source_page,confidence,status,basis,scope_key,created_at,last_verified_at) VALUES($s,$ft,$fi,$fn,$tt,$ti,$tn,$rt,$src,$page,$c,$st,$b,$scope,$at,$at); SELECT last_insert_rowid();",("$s",siteId),("$ft",from.Type),("$fi",from.Id),("$fn",from.Name.Trim()),("$tt",to.Type),("$ti",to.Id),("$tn",to.Name.Trim()),("$rt",type),("$src",source),("$page",sourcePage),("$c",confidence),("$st",status),("$b",basis),("$scope",string.IsNullOrWhiteSpace(scopeKey)?null:scopeKey.Trim()),("$at",now));c.Execute("INSERT INTO relationship_evidence(relationship_id,source_id,basis) VALUES($r,$s,$b)",("$r",id),("$s",source),("$b",basis));
        var conflict=c.OptionalLong("SELECT id FROM entity_relationships WHERE site_id=$s AND id<>$id AND from_entity_type=$ft AND COALESCE(from_entity_id,-1)=COALESCE($fi,-1) AND from_entity_name=$fn COLLATE NOCASE AND relationship_type=$rt AND status<>'superseded' AND NOT(to_entity_type=$tt AND COALESCE(to_entity_id,-1)=COALESCE($ti,-1) AND to_entity_name=$tn COLLATE NOCASE) AND ($exclusive=1 OR ($scope IS NOT NULL AND scope_key=$scope COLLATE NOCASE)) LIMIT 1",("$s",siteId),("$id",id),("$ft",from.Type),("$fi",from.Id),("$fn",from.Name),("$rt",type),("$tt",to.Type),("$ti",to.Id),("$tn",to.Name),("$exclusive",type=="RUNS_ON"?1:0),("$scope",string.IsNullOrWhiteSpace(scopeKey)?null:scopeKey.Trim()));
        if(conflict.HasValue){c.Execute("UPDATE entity_relationships SET status='conflicting' WHERE id IN($a,$b)",("$a",id),("$b",conflict.Value));c.Execute("INSERT INTO relationship_conflicts(site_id,existing_relationship_id,proposed_relationship_id,status,created_at) VALUES($s,$a,$b,'unresolved',$at)",("$s",siteId),("$a",conflict.Value),("$b",id),("$at",now));}return id;
    }
    public void SetRelationshipStatus(long id,string status){if(status is not("confirmed" or "superseded"))throw new InvalidOperationException("Unsupported status change.");using var c=Open();using var tx=c.BeginTransaction();var now=DateTimeOffset.Now.ToString("O");c.Execute("UPDATE entity_relationships SET status=$s,last_verified_at=$at WHERE id=$id",("$s",status),("$at",now),("$id",id));var others=c.Query(r=>r.GetInt64(0),"SELECT CASE WHEN existing_relationship_id=$id THEN proposed_relationship_id ELSE existing_relationship_id END FROM relationship_conflicts WHERE (existing_relationship_id=$id OR proposed_relationship_id=$id) AND status='unresolved'",("$id",id));foreach(var other in others)c.Execute("UPDATE entity_relationships SET status=$s,last_verified_at=$at WHERE id=$id AND status='conflicting'",("$s",status=="confirmed"?"superseded":"confirmed"),("$at",now),("$id",other));c.Execute("UPDATE relationship_conflicts SET status='resolved',resolved_at=$at WHERE (existing_relationship_id=$id OR proposed_relationship_id=$id) AND status='unresolved'",("$at",now),("$id",id));tx.Commit();}
