    private static void RecordManual(SqliteConnection c,long site,string entityType,long entityId,string action,IEnumerable<(string Field,string? Value)> values){var source=c.Insert("INSERT INTO evidence_sources(site_id,file_name,source_type,imported_at,content_hash) VALUES($s,$f,'MANUAL',$at,$h); SELECT last_insert_rowid();",("$s",site),("$f",action),("$at",DateTimeOffset.Now.ToString("O")),("$h",Guid.NewGuid().ToString("N")));foreach(var item in values.Where(x=>!string.IsNullOrWhiteSpace(x.Value))){c.Execute("UPDATE facts SET status='superseded' WHERE site_id=$s AND entity_type=$e AND entity_id=$id AND field_name=$f AND value<>$v AND status<>'conflicting'",("$s",site),("$e",entityType),("$id",entityId),("$f",item.Field),("$v",item.Value));var fact=c.Insert("INSERT INTO facts(site_id,entity_type,entity_id,field_name,value,confidence,status) VALUES($s,$e,$id,$f,$v,1.0,'confirmed'); SELECT last_insert_rowid();",("$s",site),("$e",entityType),("$id",entityId),("$f",item.Field),("$v",item.Value));c.Execute("INSERT INTO fact_evidence(fact_id,source_id) VALUES($f,$src)",("$f",fact),("$src",source));}}
    private static void EnsureColumn(SqliteConnection c,string table,string column,string type){using var check=c.CreateCommand();check.CommandText=$"PRAGMA table_info({table})";using var reader=check.ExecuteReader();var found=false;while(reader.Read())if(reader.GetString(1).Equals(column,StringComparison.OrdinalIgnoreCase)){found=true;break;}reader.Close();if(!found)c.Execute($"ALTER TABLE {table} ADD COLUMN {column} {type}");}
}

internal static class SqliteExtensions
{
    public static void Execute(this SqliteConnection c,string sql,params (string,object?)[] ps) { using var x=c.CreateCommand(); x.CommandText=sql; foreach(var p in ps)x.Parameters.AddWithValue(p.Item1,p.Item2??DBNull.Value); x.ExecuteNonQuery(); }
    public static long Insert(this SqliteConnection c,string sql,params (string,object?)[] ps) { using var x=c.CreateCommand(); x.CommandText=sql; foreach(var p in ps)x.Parameters.AddWithValue(p.Item1,p.Item2??DBNull.Value); return (long)x.ExecuteScalar()!; }
    public static long? OptionalLong(this SqliteConnection c,string sql,params (string,object?)[] ps) { using var x=c.CreateCommand();x.CommandText=sql;foreach(var p in ps)x.Parameters.AddWithValue(p.Item1,p.Item2??DBNull.Value);var value=x.ExecuteScalar();return value is null or DBNull?null:Convert.ToInt64(value); }
    public static List<T> Query<T>(this SqliteConnection c,Func<SqliteDataReader,T> map,string sql,params (string,object?)[] ps) { using var x=c.CreateCommand(); x.CommandText=sql; foreach(var p in ps)x.Parameters.AddWithValue(p.Item1,p.Item2??DBNull.Value); using var r=x.ExecuteReader(); var list=new List<T>(); while(r.Read())list.Add(map(r)); return list; }
}
